    rettungswuerfe: { GES: 11, KON: 13, WEI: 12 },
    fertigkeiten: { "Täuschung": 10, "Wahrnehmung": 12, "Heimlichkeit": 11 },
    schadensresistenzen: ["Feuer", "Blitz"],
    schadensimmunitaeten: ["Kälte", "Gift", "Wucht von nichtmagischen Waffen", "Stich von nichtmagischen Waffen", "Hieb von nichtmagischen Waffen"],
