    rettungswuerfe: { GES: 7, KON: 8 },
    fertigkeiten: { "Wahrnehmung": 10, "Heimlichkeit": 11 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Donner"],
    verwundbarkeiten: [],
