    rettungswuerfe: { GES: 8, KON: 11, INT: 8, WEI: 8, CHA: 9 },
    fertigkeiten: { "Arkane Kunde": 8, "Täuschung": 9, "Menschenkenntnis": 8, "Medizin": 8, "Wahrnehmung": 8, "Heimlichkeit": 8 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Gift"],
