    fertigkeiten: { "Athletik": 8, "Täuschung": 8, "Wahrnehmung": 5 },
    schadensresistenzen: ["Wucht", "Donner"],
    schadensimmunitaeten: ["Kälte", "Blitz", "Nekrotisch", "Gift"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Erschöpft", "Verängstigt", "Gelähmt", "Versteinert", "Vergiftet"],
