    tp: 370, tp_wuerfel: "20W20+160",
    bewegung: { "Gehen": "18 m", "Klettern": "18 m" },
    attribute: { STR: 29, DEX: 19, CON: 27, INT: 18, WIS: 18, CHA: 22 },
    rettungswuerfe: { STR: 17, GES: 12, WEI: 12 },
    fertigkeiten: { "Arkanes": 12, "Einsicht": 12, "Einschüchterung": 14, "Wahrnehmung": 12, "Religion": 12 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Säure", "Feuer", "Blitz", "Gift", "Wucht von nichtmagischen Waffen", "Stich von nichtmagischen Waffen", "Hieb von nichtmagischen Waffen"],
    verwundbarkeiten: ["Kälte"],
