    bewegung: { "Gehen": "4,5 m", "Klettern": "3 m" },
    attribute: { STR: 4, DEX: 6, CON: 17, INT: 1, WIS: 1, CHA: 10 },
    rettungswuerfe: {},
    fertigkeiten: { "Täuschung": 4 },
    schadensresistenzen: [],
