    rettungswuerfe: { GES: 9, KON: 10, INT: 10, WEI: 10, CHA: 10 },
    fertigkeiten: { "Athletik": 13, "Geschichte": 10, "Einsicht": 10, "Wahrnehmung": 10, "Überzeugung": 10 },
    schadensresistenzen: ["Wucht von nichtmagischen Waffen", "Stich von nichtmagischen Waffen", "Hieb von nichtmagischen Waffen"],
    schadensimmunitaeten: ["Säure", "Donner"],
