    attribute: { STR: 20, DEX: 14, CON: 18, INT: 10, WIS: 15, CHA: 16 },
    rettungswuerfe: {},
    fertigkeiten: { "Wahrnehmung": 5, "Heimlichkeit": 5 },
    schadensresistenzen: ["Blitz", "Donner", "Wucht von nichtmagischen Waffen, die nicht versilbert sind", "Stich von nichtmagischen Waffen, die nicht versilbert sind", "Hieb von nichtmagischen Waffen, die nicht versilbert sind"],
    schadensimmunitaeten: [],
    verwundbarkeiten: ["Strahlend", "Versilberte Waffen"],
