    bewegung: { "Gehen": "3 m", "Schwimmen": "12 m", "Fliegen": "12 m (schwebend, nur in Ätherform)" },
    attribute: { STR: 21, DEX: 9, CON: 15, INT: 18, WIS: 15, CHA: 18 },
