    fertigkeiten: { "Täuschung": 8, "Wahrnehmung": 5, "Überleben": 5 },
    schadensresistenzen: ["Kälte", "Feuer", "Wucht von nichtmagischen Waffen", "Stich von nichtmagischen Waffen", "Hieb von nichtmagischen Waffen"],
    schadensimmunitaeten: ["Blitz", "Donner", "Gift"],
