    fertigkeiten: { "Tierführung": 8, "Einsicht": 5, "Einschüchtern": 6, "Wahrnehmung": 8, "Heimlichkeit": 8 },
    schadensresistenzen: ["Wucht, Stich und Hieb von nichtmagischen Waffen"],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
