    bewegung: { "Gehen": "1,5 m", "Fliegen": "15 m", "Schwimmen": "12 m" },
    attribute: { STR: 16, DEX: 14, CON: 15, INT: 4, WIS: 12, CHA: 5 },
    rettungswuerfe: {},
